export function catalogEndpointCandidates(input: string, catalog: CatalogBundle = defaultCatalog()): string[] {
	const exact = normalizeCatalogSourceUrl(input, catalog);
	const parsed = new URL(exact);
	const path = parsed.pathname.replace(/\/+$/u, "") || "/";
	let conventionalPath: string;
	if (path === "/") conventionalPath = "/v1/jouzu/model-catalog";
	else if (path.endsWith("/v1")) conventionalPath = `${path}/jouzu/model-catalog`;
	else if (path.endsWith("/v1/jouzu")) conventionalPath = `${path}/model-catalog`;
	else conventionalPath = `${path}/v1/jouzu/model-catalog`;
	const conventional = new URL(parsed.href);
	conventional.pathname = conventionalPath;
	const candidates = [exact, conventional.href];
	return [...new Set(candidates)];
}

export interface AcquireStateLockOptions {
	path: string;
	staleMs?: number;
	describe: string;
	now?: Date;
	/** Maps a busy inspection to the caller's domain-specific error. */
	onBusy: (inspection: StateLockInspection) => Error;
}

function releaseToken(path: string, token: string): void {
	try {
		const metadata = lstatSync(path);
		if (!metadata.isFile() || metadata.isSymbolicLink()) return;
		const parsed = JSON.parse(readLockRecord(path)) as { token?: unknown };
		if (parsed.token === token) unlinkSync(path);
	} catch {}
}

/**
 * Acquire a state lock shared by the updater, profile, and keybinding
 * operations. The lock records a PID, started-at timestamp, and a release
 * token. A lock held by a live process is always refused; a dead owner's lock
 * or an owner-unknown legacy lock is refused while younger than the stale
 * threshold and recovered automatically once it is older. Recovery and release
 * inspect and unlink separately; they do not atomically exclude a successor.
 * Returns a token-matched release function.
 */
export function acquireStateLock(options: AcquireStateLockOptions): () => void {
	const now = options.now ?? new Date();
	const staleMs = options.staleMs ?? STATE_LOCK_STALE_MS;
	ensurePrivateDirectory(dirname(options.path));
	const token = randomUUID();
	const record: StateLockRecord = { pid: process.pid, startedAt: now.toISOString(), token };
	const writeNew = (): void => {
		const descriptor = openSync(options.path, "wx", 0o600);
		writeFileSync(descriptor, `${JSON.stringify(record)}\n`);
		fsyncSync(descriptor);
		closeSync(descriptor);
	};
	try {
		writeNew();
	} catch (error) {
		if (!(error instanceof Error && "code" in error && error.code === "EEXIST")) throw error;
		const inspection = inspectStateLock(options.path, now);
		if (inspection.status === "free") {
			writeNew();
			return () => releaseToken(options.path, token);
		}
		if (inspection.status === "held-live" || inspection.status === "invalid" || inspection.status === "unreadable") {
			throw options.onBusy(inspection);
		}
		// held-dead or owner-unknown: refuse while younger than the threshold,
		// recover automatically once stale.
		if (inspection.ageMs === null || inspection.ageMs <= staleMs) {
			throw options.onBusy(inspection);
		}
		unlinkSync(options.path);
		writeNew();
		return () => releaseToken(options.path, token);
	}
	return () => releaseToken(options.path, token);
}

/** The age a lock description reports, as the protected value the catalog text takes. */
export function ageText(ageMs: number): string {
	const totalSeconds = Math.max(0, Math.floor(ageMs / 1000));
	const minutes = Math.floor(totalSeconds / 60);
	const seconds = totalSeconds % 60;
	return minutes > 0 ? `${minutes}m ${seconds}s` : `${seconds}s`;
}

export async function applyProviderReceipts(codingAgentRoot, checkOnly = false) {
	const require = createRequire(join(codingAgentRoot, "package.json"));
	let packageRoot;
	for (const directory of require.resolve.paths("@earendil-works/pi-ai") ?? []) {
		const candidate = join(directory, "@earendil-works/pi-ai");
		try {
			await readFile(join(candidate, "package.json"));
			packageRoot = candidate;
			break;
		} catch (error) {
			if (error.code !== "ENOENT") throw error;
		}
	}
	if (!packageRoot) throw new Error("Pi provider package is missing.");
	const manifestPath = "upstream/pi-provider-receipts/patch.lock.json";
	const manifest = await readFile(join(root, manifestPath), "utf8");
	const lock = JSON.parse(manifest);
	const pin = JSON.parse(await readFile(join(root, "upstream/pi.lock.json"), "utf8"));
	const records = pin.deviations?.filter((record) => record.path === manifestPath) ?? [];
	if (records.length !== 1 || records[0].sha256 !== sha(manifest))
		throw new Error("Pi provider receipt manifest does not match the pinned deviation");
	const pkg = JSON.parse(await readFile(join(packageRoot, "package.json"), "utf8"));
	if (
		lock.schemaVersion !== 1 ||
		lock.package !== "@earendil-works/pi-ai" ||
		pkg.name !== lock.package ||
		pkg.version !== lock.version ||
		lock.version !== pin.packages["@earendil-works/pi-coding-agent"]?.version
	)
		throw new Error("Pi provider receipt package identity mismatch");
	if (JSON.stringify(Object.keys(lock.files).sort()) !== JSON.stringify([...paths].sort()))
		throw new Error("Pi provider receipt path manifest mismatch");
	const writes = [];
	for (const path of paths) {
		const original = await readFile(join(packageRoot, path), "utf8");
		const hashes = lock.files[path];
		if (sha(original) === hashes.after) continue;
		if (checkOnly || sha(original) !== hashes.before) throw new Error(`Pi provider receipt hash mismatch: ${path}`);
		const patched = transform(path, original);
		if (sha(patched) !== hashes.after) throw new Error(`Pi provider receipt transformed hash mismatch: ${path}`);
		writes.push([join(packageRoot, path), patched]);
	}
	for (const [path, text] of writes) await writeFile(path, text);
	return writes.length;

	for (const base of [root, join(root, "packages/cli")]) {
		const path = join(base, "node_modules/@earendil-works/pi-coding-agent");
		try {
			roots.add(await realpath(path));
		} catch (error) {
			if (error.code !== "ENOENT") throw error;
		}
	}
	if (roots.size === 0) throw new Error("Pi package is missing; run npm ci first");
	let count = 0;
	for (const packageRoot of roots) {
		count += await applyContentPolicy(packageRoot, process.argv.includes("--check"));
		count += await applyFlowControl(packageRoot, process.argv.includes("--check"));
		count += await applyProviderReceipts(packageRoot, process.argv.includes("--check"));
	}
	for (const base of [root, join(root, "packages/cli")]) {
		count += await applyFlowControl(base, process.argv.includes("--check"));
		count += await applyProviderReceipts(base, process.argv.includes("--check"));
	}
	console.log(`Pi content-policy patch verified (${roots.size} package trees, ${count} files written)`);
}
